begin;
create table public.website_visits(id text primary key,visitor text not null,country text not null,region text not null,city text not null,device text not null,browser text not null,referrer text not null,first_seen timestamptz not null default now(),last_seen timestamptz not null default now(),last_path text not null);
create table public.website_visit_events(id bigint generated always as identity primary key,visit text not null references website_visits(id) on delete cascade,path text not null,action text not null,created_at timestamptz not null default now());
create index on website_visits(last_seen);create index on website_visits(visitor);create index on website_visit_events(created_at);
alter table website_visits enable row level security;alter table website_visit_events enable row level security;
revoke all on website_visits,website_visit_events from public,anon,authenticated;
create function record_website_visit(p jsonb,request_tag text) returns void language plpgsql security definer set search_path=public as $$declare n integer;begin
 if length(p->>'id')<>64 or length(p->>'visitor')<>64 or p->>'action' not in ('view','heartbeat','giving','merchandise','volunteer','partner','kids') or length(p->>'path')>180 then raise exception 'Invalid content.';end if;
 delete from website_visit_events where created_at<now()-interval '30 days';delete from website_visits where first_seen<now()-interval '30 days' or last_seen<now()-interval '30 days';delete from website_engagement_limits where day<current_date-1;
 insert into website_engagement_limits(day,tag) values(current_date,request_tag) on conflict(day,tag) do update set count=website_engagement_limits.count+1 returning count into n;if n>2000 then return;end if;
 insert into website_visits(id,visitor,country,region,city,device,browser,referrer,last_path) values(p->>'id',p->>'visitor',left(p->>'country',2),left(p->>'region',80),left(p->>'city',80),left(p->>'device',20),left(p->>'browser',30),left(p->>'referrer',100),p->>'path') on conflict(id) do update set last_seen=now(),last_path=excluded.last_path where website_visits.visitor=excluded.visitor;
 if p->>'action'<>'heartbeat' and (select count(*) from website_visit_events where visit=p->>'id')<500 then insert into website_visit_events(visit,path,action) values(p->>'id',p->>'path',p->>'action');end if;
end $$;
create function forget_website_visits(visitor_key text) returns void language sql security definer set search_path=public as $$delete from website_visits where visitor=visitor_key$$;
create function website_analytics(start_at timestamptz,end_at timestamptz,selected_country text default '',page_offset integer default 0) returns jsonb language plpgsql security definer set search_path=public as $$declare result jsonb;begin
 if not website_role(array['administrator']) then raise exception 'Access denied.';end if;
 if end_at<=start_at or end_at-start_at>interval '91 days' or page_offset<0 then raise exception 'Invalid content.';end if;
 delete from website_visits where first_seen<now()-interval '30 days';delete from website_visit_events where created_at<now()-interval '30 days';
 with visits as(select * from website_visits where first_seen>=start_at and first_seen<end_at and (selected_country='' or country=selected_country)),events as(select e.* from website_visit_events e join visits v on v.id=e.visit where e.created_at>=start_at and e.created_at<end_at)
 select jsonb_build_object('sessions',(select count(*) from visits),'visitors',(select count(distinct visitor) from visits),'live',(select count(*) from website_visits where last_seen>now()-interval '2 minutes' and (selected_country='' or country=selected_country)),'pageviews',(select count(*) from events where action='view'),'actions',(select count(*) from events where action not in ('view','heartbeat')),'countries',(select coalesce(jsonb_agg(x),'[]') from(select country,count(*) sessions from visits group by country order by count(*) desc limit 30)x),'pages',(select coalesce(jsonb_agg(x),'[]') from(select path,count(*) views from events where action='view' group by path order by count(*) desc limit 20)x),'days',(select coalesce(jsonb_agg(x),'[]') from(select (created_at at time zone 'Africa/Kampala')::date as "day",count(*) views from events where action='view' group by 1 order by 1)x),'history',(select coalesce(jsonb_agg(x),'[]') from(select id,country,region,city,device,browser,referrer,first_seen,last_seen,last_path from visits order by last_seen desc limit 50 offset least(page_offset,10000))x)) into result;return result;
end $$;
create function website_visit_history(visit_key text) returns jsonb language plpgsql security definer set search_path=public as $$begin if not website_role(array['administrator']) then raise exception 'Access denied.';end if;return (select coalesce(jsonb_agg(x),'[]') from(select path,action,created_at from website_visit_events where visit=visit_key order by created_at desc limit 200)x);end $$;
revoke all on function record_website_visit(jsonb,text),forget_website_visits(text),website_analytics(timestamptz,timestamptz,text,integer),website_visit_history(text) from public,anon,authenticated;
grant execute on function record_website_visit(jsonb,text),forget_website_visits(text) to service_role;
grant execute on function website_analytics(timestamptz,timestamptz,text,integer),website_visit_history(text) to authenticated;
create function prune_website_visits() returns void language sql security definer set search_path=public as $$delete from website_visits where first_seen<now()-interval '30 days';delete from website_visit_events where created_at<now()-interval '30 days'$$;
revoke all on function prune_website_visits() from public,anon,authenticated;grant execute on function prune_website_visits() to service_role;
commit;
